skillData = FileAttachment("outputs/us-employer-inventory/web/skills-data.json").json()
scope = skillData.scopes[scopeKey]
skillRows = scope.skills.map(d =&gt; ({...d, share: d.denominator ? 100 * d.records / d.denominator : 0})).filter(d =&gt; d.name.toLowerCase().includes(skillSearch.trim().toLowerCase())).sort((a, b) =&gt; b[skillMetric] - a[skillMetric] || a.name.localeCompare(b.name))
selectedSkill = skillRows.find(d =&gt; d.name === skillName)
evidenceRows = selectedSkill ? selectedSkill.sources.filter(d =&gt; evidenceEmployer === "All employers" || d.company === evidenceEmployer) : []





































Explore the evidence

viewof scopeKey = Inputs.select(new Map([["All US postings", "us"], ["Analytics-relevant US postings", "analytics"], ["Postings mentioning tracked data products / datasets", "data"]]), {label: "Evidence scope", value: "us"})
viewof skillSearch = Inputs.text({label: "Find a skill", placeholder: "SQL, Python, claims…", value: ""})
viewof skillMetric = Inputs.select(new Map([["Posting mentions", "records"], ["Share of scope (%)", "share"], ["Employers", "companies"]]), {label: "Compare", value: "records"})























html`&lt;p class="context-note" role="status"&gt;${scope.records.toLocaleString("en-US")} US postings across ${scope.companies} employers in this scope. Showing ${skillRows.length} matching skills. Shares use all ${scope.records.toLocaleString("en-US")} postings in the selected scope, including those without tracked skill mentions.&lt;/p&gt;`









Skills in employer postings



bubbleView = {
  if (!skillRows.length) return html`&lt;p role="status"&gt;No skills match this search. Clear the search or try another term.&lt;/p&gt;`;
  const control = viewof skillName;
  const peak = Math.max(1, ...scope.skills.map(d =&gt; skillMetric === "share" ? 100 * d.records / d.denominator : d[skillMetric]));
  const choose = name =&gt; {
    if (control.value === name) return;
    control.value = name;
    control.dispatchEvent(new Event("input", {bubbles: true}));
  };
  return html`&lt;div class="skill-bubbles" role="group" aria-label="Skills by selected measure"&gt;${skillRows.map(d =&gt; {
    const diameter = 188 * Math.sqrt(d[skillMetric] / peak);
    const value = skillMetric === "share" ? d.share.toFixed(1) + "%" : d[skillMetric].toLocaleString("en-US");
    const button = html`&lt;button type="button" class="ojs-bubble" data-skill=${d.name} style=${`--bubble-size:${diameter}px;--bubble-slot:${Math.max(100,diameter)}px`} aria-pressed="false" aria-controls="selected-skill-summary" aria-label=${`${d.name}: ${d.records} postings, ${d.companies} employers, ${d.share.toFixed(1)} percent. Show evidence.`}&gt;
      &lt;span class="bubble-disc" aria-hidden="true"&gt;${diameter &gt;= 75 ? html`&lt;strong&gt;${value}&lt;/strong&gt;` : ""}&lt;/span&gt;
      &lt;span class="bubble-caption"&gt;${d.name}${diameter &lt; 75 ? html`&lt;strong&gt;${value}&lt;/strong&gt;` : ""}&lt;/span&gt;
    &lt;/button&gt;`;
    button.addEventListener("click", () =&gt; choose(d.name));
    button.addEventListener("focus", () =&gt; choose(d.name));
    button.addEventListener("mouseenter", () =&gt; {
      if (!document.activeElement?.closest(".analytics-evidence, .skill-detail")) choose(d.name);
    });
    return button;
  })}&lt;/div&gt;`;
}







bubbleSelection = {
  for (const button of bubbleView.querySelectorAll("[data-skill]")) button.setAttribute("aria-pressed", String(button.dataset.skill === skillName));
}









selectedSkill ? html`&lt;div role="status"&gt;&lt;h3&gt;${selectedSkill.name}&lt;/h3&gt;
&lt;div class="skill-detail-metrics"&gt;&lt;div&gt;&lt;strong&gt;${selectedSkill.records.toLocaleString("en-US")}&lt;/strong&gt;&lt;span&gt;postings&lt;/span&gt;&lt;/div&gt;&lt;div&gt;&lt;strong&gt;${selectedSkill.companies}&lt;/strong&gt;&lt;span&gt;employers&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;
&lt;p&gt;${selectedSkill.share.toFixed(1)}% of the selected scope. Mentions include required and preferred skills.&lt;/p&gt;
&lt;a href="#source-evidence"&gt;Inspect employer source records ↓&lt;/a&gt;&lt;/div&gt;` : html`&lt;p role="status"&gt;Choose a skill to inspect its evidence.&lt;/p&gt;`









html`&lt;p class="tiny"&gt;Bubble area represents ${skillMetric === "share" ? "share of postings in the selected scope" : skillMetric === "companies" ? "the number of employers" : "the number of postings"}. Hover, tap or focus a bubble to inspect its evidence. Sizes use the full scope, so searching does not rescale bubbles.&lt;/p&gt;`







Each skill counts once per posting; categories overlap and include required and preferred mentions. These percentages describe the collection, not the wider job market. Small bubbles have their values below the circle to keep labels readable.




