Inspect the source evidence

viewof skillName = Inputs.select(skillRows.map(d =&gt; d.name), {label: "Skill", disabled: !skillRows.length})
viewof evidenceEmployer = Inputs.select(["All employers", ...new Set(selectedSkill ? selectedSkill.sources.map(d =&gt; d.company).sort() : [])], {label: "Source employer", value: "All employers", disabled: !selectedSkill})
















selectedSkill ? html`&lt;p role="status"&gt;&lt;strong&gt;${selectedSkill.name}&lt;/strong&gt; appears in &lt;strong&gt;${selectedSkill.records.toLocaleString("en-US")}&lt;/strong&gt; postings (${selectedSkill.share.toFixed(1)}% of this scope) across &lt;strong&gt;${selectedSkill.companies}&lt;/strong&gt; employers. Showing ${evidenceRows.length.toLocaleString("en-US")} source records.&lt;/p&gt;` : html`&lt;p role="status"&gt;No skill selected. Clear the search to inspect evidence.&lt;/p&gt;`







Inputs.table(evidenceRows, {select: false, rows: 8, maxHeight: 360, layout: "auto", columns: ["company", "id", "url", "evidence"], header: {company: "Employer", id: "Posting identity", url: "Source", evidence: "Evidence annotation"}, format: {url: d =&gt; /^https?:\/\//i.test(d || "") ? html`&lt;a href=${d} target="_blank" rel="noopener"&gt;Employer posting ↗&lt;/a&gt;` : "No source URL"}})









